// Cloudflare Pages entry point. The static pages are bundled into this file at build time
// (see build.mjs), so one upload carries the whole app.
import ids from "../../agents/ids.json";
import { ElevenClient } from "../lib/eleven";
import { D1Store } from "./d1-store";
import { handleApi } from "./app";
// @ts-ignore generated by build.mjs
import { ASSETS } from "../../.build/assets.generated.js";

interface Env {
  DB: D1Database;
  ELEVENLABS_API_KEY?: string;
  TOOL_SECRET?: string;
}

const PAGES: Record<string, string> = { "/": "/home.html", "/setup": "/index.html", "/interview": "/interview.html", "/report": "/report.html", "/chat": "/chat.html", "/role": "/role.html", "/feedback": "/feedback.html", "/recruit": "/recruit.html", "/jd": "/jd.html", "/fit": "/fit.html", "/room": "/room.html" };
const TYPES: Record<string, string> = {
  html: "text/html; charset=utf-8",
  css: "text/css; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  mjs: "text/javascript; charset=utf-8",
};

const SECURITY = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "no-referrer",
  "permissions-policy": "microphone=(self)",
};

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) {
      // Voice previews never change, so serve them from Cloudflare's cache after the first request.
      const cacheable = request.method === "GET" && /^\/api\/voices\/[^/]+\/preview$/.test(url.pathname);
      const cache = (caches as unknown as { default: Cache }).default;
      if (cacheable) {
        const hit = await cache.match(request);
        if (hit) return hit;
      }
      const response = await handleApi(request, {
        store: new D1Store(env.DB),
        eleven: new ElevenClient(env.ELEVENLABS_API_KEY ?? ""),
        agents: ids,
        toolSecret: env.TOOL_SECRET ?? "",
        now: () => Date.now(),
        newId: () => crypto.randomUUID().replace(/-/g, ""),
      });
      if (cacheable && response.ok) ctx.waitUntil(cache.put(request, response.clone()));
      return response;
    }
    const path = PAGES[url.pathname.replace(/\/$/, "") || "/"] ?? url.pathname;
    const body = (ASSETS as Record<string, string>)[path];
    if (body === undefined || (request.method !== "GET" && request.method !== "HEAD")) {
      return new Response("Not found", { status: 404, headers: { "content-type": "text/plain", ...SECURITY } });
    }
    const ext = path.split(".").pop() ?? "";
    return new Response(request.method === "HEAD" ? null : body, {
      headers: {
        "content-type": TYPES[ext] ?? "application/octet-stream",
        // Nothing is cached by the browser, so a deploy shows up on the next normal reload.
        "cache-control": "no-cache, must-revalidate",
        ...SECURITY,
      },
    });
  },
};
